// Telegram gửi một "update". Chỉ xử lý tin nhắn mới trong chat riêng với bot.
const req = $('Telegram Webhook').first().json;
const cfg = $('Cấu hình').first().json;
const headers = req.headers ?? {};
const update = req.body ?? {};

// Telegram gửi kèm secret_token đã đăng ký ở setWebhook. Sai hoặc chưa cấu hình thì bỏ qua
const secretOk = !!cfg.webhookSecret && headers['x-telegram-bot-api-secret-token'] === cfg.webhookSecret;
const msg = update.message;
const chatId = msg?.chat?.id;
const isPrivate = msg?.chat?.type === 'private';

if (!secretOk || !cfg.botToken || !msg || !chatId || !isPrivate || msg.from?.is_bot) {
  return [{ json: { valid: false, reason: !secretOk ? 'secret' : !cfg.botToken ? 'no-token' : 'not-a-private-message' } }];
}

const text = String(msg.text ?? '').trim();
const firstName = String(msg.from?.first_name ?? '').slice(0, 50);
let reply = null;

if (!text) {
  reply = 'Hiện chúng tôi chỉ đọc được tin nhắn chữ. Anh/chị vui lòng gõ câu hỏi, ví dụ: "Tìm căn hộ ở Đà Nẵng dưới 5 tỷ".';
} else if (/^\/(start|help)\b/i.test(text)) {
  reply = `Chào ${firstName ? 'anh/chị ' + firstName : 'anh/chị'}! Chúng tôi là trợ lý tư vấn của RealEstate AI.\n\n` +
    'Anh/chị có thể:\n- Tìm nhà: "Căn hộ ở TP.HCM dưới 3 tỷ"\n- Đặt lịch xem: "Tôi muốn xem căn số 2 vào sáng thứ 7"\n- Tra lịch đã đặt: gửi email và số điện thoại đã dùng khi đặt';
}

return [{
  json: {
    valid: true,
    chatId,
    sessionKey: `tg-${chatId}`,
    firstName,
    // giới hạn độ dài để tránh tin quá dài làm tốn token
    text: text.slice(0, 1000),
    needAi: reply === null,
    reply,
  },
}];

