// Kiểm tra câu trả lời của Agent trước khi gửi khách
const ctx = $('Chuẩn hoá tin nhắn').item.json;
let reply = String($json.output ?? '').trim();
// Telegram gửi văn bản thuần (không parse_mode), nên bỏ dấu markdown nếu model vẫn dùng
reply = reply.replace(/\*\*(.+?)\*\*/g, '$1').replace(/^#+\s*/gm, '');
reply = reply.charAt(0).toUpperCase() + reply.slice(1);

let usedFallback = false;
if (!reply || reply.includes('{{') || reply.length > 3500) {
  usedFallback = true;
  reply = 'Xin lỗi anh/chị, chúng tôi chưa trả lời được câu này. Anh/chị thử hỏi lại ngắn gọn hơn, hoặc để lại số điện thoại để nhân viên gọi lại nhé.';
}
return [{ json: { chatId: ctx.chatId, reply, usedFallback } }];
